-- Jora Supabase baseline. Run in this project's SQL Editor.
create extension if not exists pgcrypto;
create type public.jora_role as enum ('user','vendor','partner','admin');
create type public.jora_order_status as enum ('placed','accepted_by_vendor','preparing','ready','partner_assigned','partner_accepted','picked_up','on_the_way','delivered','cancelled','rejected');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,role public.jora_role not null default 'user',name text not null default '',phone text default '',address text default '',pincode text default '',lat numeric,lng numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(),name text not null unique,image_url text,created_at timestamptz not null default now());
create table public.vendors (id uuid primary key default gen_random_uuid(),user_id uuid unique not null references public.profiles(id) on delete cascade,name text not null,address text default '',phone text default '',lat numeric,lng numeric,is_open boolean not null default true,image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.vendors(id) on delete cascade,category_id uuid references public.categories(id),name text not null,description text default '',price numeric(12,2) not null check(price>=0),tax_percent numeric(5,2) not null default 0 check(tax_percent between 0 and 100),image_url text,stock integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.delivery_partners (id uuid primary key default gen_random_uuid(),user_id uuid unique not null references public.profiles(id) on delete cascade,name text not null,phone text default '',vehicle text default '',is_online boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.carts (id uuid primary key default gen_random_uuid(),user_id uuid unique not null references public.profiles(id) on delete cascade,vendor_id uuid references public.vendors(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table public.cart_items (id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts(id) on delete cascade,product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),unique(cart_id,product_id));
create table public.orders (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),vendor_id uuid not null references public.vendors(id),partner_id uuid references public.delivery_partners(id),status public.jora_order_status not null default 'placed',product_amount numeric(12,2) not null default 0,product_tax numeric(12,2) not null default 0,delivery_charge numeric(12,2) not null default 0,total numeric(12,2) not null default 0,delivery_address text not null,pincode text,delivery_lat numeric,delivery_lng numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id),name text not null,unit_price numeric(12,2) not null,tax_percent numeric(5,2) not null default 0,quantity integer not null check(quantity>0));
create table public.partner_slots (id uuid primary key default gen_random_uuid(),partner_id uuid not null references public.delivery_partners(id) on delete cascade,slot_name text not null check(slot_name in ('Morning 7:30-10:30','Afternoon 11:00-3:00','Evening 4:00-6:00','Night 7:00-10:00')),slot_date date not null,booked boolean not null default true,unique(partner_id,slot_name,slot_date)); create table public.partner_locations (id uuid primary key default gen_random_uuid(),partner_id uuid not null references public.delivery_partners(id) on delete cascade,order_id uuid references public.orders(id) on delete cascade,lat numeric not null,lng numeric not null,accuracy numeric,heading numeric,speed numeric,created_at timestamptz not null default now());
create table public.complaints (id uuid primary key default gen_random_uuid(),raised_by uuid not null references public.profiles(id),order_id uuid references public.orders(id),subject text not null,message text not null,status text not null default 'open',created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table public.complaint_replies (id uuid primary key default gen_random_uuid(),complaint_id uuid not null references public.complaints(id) on delete cascade,author_id uuid not null references public.profiles(id),message text not null,created_at timestamptz not null default now());
create table public.banners (id uuid primary key default gen_random_uuid(),title text not null,image_url text,is_active boolean not null default true,created_at timestamptz not null default now()); create table public.notifications (id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id),audience public.jora_role,title text not null,body text not null default '',read_at timestamptz,created_at timestamptz not null default now()); create table public.platform_settings (id boolean primary key default true check(id),tax_percent numeric(5,2) not null default 0,platform_fee numeric(12,2) not null default 0,delivery_rate_per_km numeric(12,2) not null default 10,updated_at timestamptz not null default now()); insert into public.platform_settings(id) values(true) on conflict do nothing; create table public.partner_earnings (id uuid primary key default gen_random_uuid(),partner_id uuid not null references public.delivery_partners(id),order_id uuid unique not null references public.orders(id),amount numeric(12,2) not null,created_at timestamptz not null default now());
create index orders_user_idx on public.orders(user_id,created_at desc); create index orders_vendor_idx on public.orders(vendor_id,created_at desc); create index products_vendor_idx on public.products(vendor_id); create index locations_order_idx on public.partner_locations(order_id,created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$; create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict do nothing;return new;end$$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.vendors enable row level security; alter table public.products enable row level security; alter table public.carts enable row level security; alter table public.cart_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.delivery_partners enable row level security; alter table public.partner_slots enable row level security; alter table public.partner_locations enable row level security; alter table public.complaints enable row level security; alter table public.complaint_replies enable row level security; alter table public.banners enable row level security; alter table public.notifications enable row level security; alter table public.platform_settings enable row level security; alter table public.partner_earnings enable row level security;
create policy "profile owner or admin" on public.profiles for all using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin()); create policy "public categories" on public.categories for select using(true); create policy "public products" on public.products for select using(is_active); create policy "public vendors" on public.vendors for select using(true); create policy "vendor products" on public.products for all using(exists(select 1 from public.vendors where id=vendor_id and user_id=auth.uid()) or public.is_admin()) with check(exists(select 1 from public.vendors where id=vendor_id and user_id=auth.uid()) or public.is_admin()); create policy "vendor record" on public.vendors for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "own cart" on public.carts for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own cart items" on public.cart_items for all using(exists(select 1 from public.carts where id=cart_id and user_id=auth.uid())) with check(exists(select 1 from public.carts where id=cart_id and user_id=auth.uid())); create policy "order participants" on public.orders for select using(user_id=auth.uid() or public.is_admin() or exists(select 1 from public.vendors where id=vendor_id and user_id=auth.uid()) or exists(select 1 from public.delivery_partners where id=partner_id and user_id=auth.uid())); create policy "user orders" on public.orders for insert with check(user_id=auth.uid()); create policy "partner own record" on public.delivery_partners for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "public banners" on public.banners for select using(is_active); create policy "recipient notifications" on public.notifications for select using(user_id=auth.uid() or audience=(select role from public.profiles where id=auth.uid()) or public.is_admin()); create policy "settings readable" on public.platform_settings for select using(true); create policy "admin settings" on public.platform_settings for all using(public.is_admin()) with check(public.is_admin());
create or replace function public.calculate_price(p_items jsonb,p_distance_km numeric) returns jsonb language sql security definer set search_path=public as $$select jsonb_build_object('delivery_charge',round(p_distance_km*(select delivery_rate_per_km from public.platform_settings where id),2))$$; create or replace function public.place_order(p_vendor_id uuid,p_items jsonb,p_address text,p_pincode text,p_lat numeric,p_lng numeric,p_distance_km numeric) returns uuid language plpgsql security definer set search_path=public as $$declare oid uuid:=gen_random_uuid();begin insert into public.orders(id,user_id,vendor_id,delivery_address,pincode,delivery_lat,delivery_lng,delivery_charge,total) select oid,auth.uid(),p_vendor_id,p_address,p_pincode,p_lat,p_lng,(public.calculate_price(p_items,p_distance_km)->>'delivery_charge')::numeric,(public.calculate_price(p_items,p_distance_km)->>'delivery_charge')::numeric;return oid;end$$; create or replace function public.accept_order(p_order_id uuid) returns void language sql security definer set search_path=public as $$update public.orders set status='partner_accepted',updated_at=now() where id=p_order_id and partner_id in(select id from public.delivery_partners where user_id=auth.uid())$$; create or replace function public.reject_order(p_order_id uuid) returns void language sql security definer set search_path=public as $$update public.orders set status='ready',partner_id=null,updated_at=now() where id=p_order_id and partner_id in(select id from public.delivery_partners where user_id=auth.uid())$$; create or replace function public.book_slot(p_slot_name text,p_slot_date date) returns uuid language plpgsql security definer set search_path=public as $$declare sid uuid:=gen_random_uuid();begin insert into public.partner_slots(id,partner_id,slot_name,slot_date) select sid,id,p_slot_name,p_slot_date from public.delivery_partners where user_id=auth.uid();return sid;end$$; grant execute on function public.calculate_price(jsonb,numeric),public.place_order(uuid,jsonb,text,text,numeric,numeric,numeric),public.accept_order(uuid),public.reject_order(uuid),public.book_slot(text,date) to authenticated;
alter publication supabase_realtime add table public.orders,public.notifications,public.partner_locations,public.complaint_replies; insert into storage.buckets(id,name,public) values('product-images','product-images',true),('banners','banners',true) on conflict do nothing; create policy "product image upload" on storage.objects for insert to authenticated with check(bucket_id='product-images' and (storage.foldername(name))[1]=auth.uid()::text); create policy "banner upload admin" on storage.objects for insert to authenticated with check(bucket_id='banners' and public.is_admin());